  'Cannot open remote video URL.' => 'റിമോട്ട് വീഡിയോ URL തുറക്കാൻ കഴിയില്ല.',
  'Cannot prepare imported video file.' => 'ഇറക്കുമതി ചെയ്ത വീഡിയോ ഫയൽ തയ്യാറാക്കാൻ കഴിയില്ല.',
  'Cannot read remote video file.' => 'റിമോട്ട് വീഡിയോ ഫയൽ വായിക്കാൻ കഴിയില്ല.',
  'Imported video exceeds the maximum upload size.' => 'ഇറക്കുമതി ചെയ്ത വീഡിയോ പരമാവധി അപ്‌ലോഡ് വലുപ്പത്തേക്കാൾ കൂടുതലാണ്.',
  'Remote video file is empty.' => 'വിദൂര വീഡിയോ ഫയൽ ശൂന്യമാണ്.',
  'Video import downloader command is not configured.' => 'വീഡിയോ ഇറക്കുമതി ഡൗൺലോഡർ കമാൻഡ് കോൺഫിഗർ ചെയ്തിട്ടില്ല.',
  'Downloader did not create an importable video file.' => 'ഇറക്കുമതി ചെയ്യാവുന്ന വീഡിയോ ഫയൽ ഡൗൺലോഡർ സൃഷ്‌ടിച്ചിട്ടില്ല.',
  'Import URL is invalid.' => 'ഇറക്കുമതി URL അസാധുവാണ്.',
  'Import URL must use HTTP or HTTPS.' => 'ഇറക്കുമതി URL HTTP അല്ലെങ്കിൽ HTTPS ഉപയോഗിക്കണം.',
  'Import URL host is invalid.' => 'ഇമ്പോർട്ട് URL ഹോസ്റ്റ് അസാധുവാണ്.',
  'Import URL does not match the selected provider.' => 'ഇറക്കുമതി URL തിരഞ്ഞെടുത്ത ദാതാവുമായി പൊരുത്തപ്പെടുന്നില്ല.',
  'Import URL host cannot be resolved.' => 'ഇമ്പോർട്ട് URL ഹോസ്റ്റ് പരിഹരിക്കാൻ കഴിയില്ല.',
  'Import URL must resolve to a public host.' => 'ഇറക്കുമതി URL ഒരു പൊതു ഹോസ്റ്റിലേക്ക് പരിഹരിക്കണം.',
  'Unknown video import provider.' => 'അജ്ഞാത വീഡിയോ ഇറക്കുമതി ദാതാവ്.',
  'Saves a public video file URL and plays it from the original URL.' => 'ഒരു പൊതു വീഡിയോ ഫയൽ URL സംരക്ഷിക്കുകയും യഥാർത്ഥ URL-ൽ നിന്ന് പ്ലേ ചെയ്യുകയും ചെയ്യുന്നു.',
  'Fetches YouTube details and plays with the YouTube embed player.' => 'YouTube വിശദാംശങ്ങൾ ലഭ്യമാക്കുകയും YouTube എംബഡ് പ്ലേയർ ഉപയോഗിച്ച് കളിക്കുകയും ചെയ്യുന്നു.',
  'Fetches Vimeo details and plays with the Vimeo embed player.' => 'Vimeo വിശദാംശങ്ങൾ ലഭ്യമാക്കുകയും Vimeo എംബെഡ് പ്ലെയറിൽ കളിക്കുകയും ചെയ്യുന്നു.',
  'Fetches Dailymotion details and plays with the Dailymotion embed player.' => 'Dailymotion വിശദാംശങ്ങൾ ലഭ്യമാക്കുകയും Dailymotion എംബെഡ് പ്ലേയർ ഉപയോഗിച്ച് കളിക്കുകയും ചെയ്യുന്നു.',
  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'പ്രവർത്തനക്ഷമമാക്കിയ ഒരു സേവനം തിരഞ്ഞെടുത്ത് ഒരു പൊതു വീഡിയോ URL ഒട്ടിക്കുക. PlayHub വിശദാംശങ്ങൾ ലഭ്യമാക്കുകയും യഥാർത്ഥ ദാതാവിൽ നിന്ന് പ്ലേ ചെയ്യുകയും ചെയ്യും.',
