  'Saving provider video' => 'ദാതാവിൻ്റെ വീഡിയോ സംരക്ഷിക്കുന്നു',
  'Fetched from provider' => 'ദാതാവിൽ നിന്ന് ലഭിച്ചതാണ്',
  'Fetch details to preview' => 'പ്രിവ്യൂ ചെയ്യാൻ വിശദാംശങ്ങൾ ലഭ്യമാക്കുക',
  'Provider thumbnails are saved as remote metadata.' => 'ദാതാവിൻ്റെ ലഘുചിത്രങ്ങൾ റിമോട്ട് മെറ്റാഡാറ്റയായി സംരക്ഷിച്ചിരിക്കുന്നു.',
